{
  "ruleset_id": "kulturnyy-grant-gorodskaya-scena",
  "rules": [
    {
      "description": "Руководитель проекта должен быть совершеннолетним (не младше 18 лет).",
      "severity": "critical",
      "category": "age",
      "condition": {
        "field": "team.project_lead_age",
        "op": "ge",
        "value": 18
      }
    },
    {
      "description": "Заявитель должен обеспечить не менее 20% бюджета за счёт софинансирования.",
      "severity": "critical",
      "category": "co_financing",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "Для очных мероприятий должно быть представлено согласие площадки.",
      "severity": "critical",
      "category": "venue_consent",
      "condition": {
        "field": "documents.venue_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Запрашиваемый грант не должен превышать 1 500 000 рублей.",
      "severity": "critical",
      "category": "grant_amount",
      "condition": {
        "field": "application.requested_rub",
        "op": "le",
        "value": 1500000
      }
    }
  ]
}

{
  "ruleset_id": "programma-dopolnitelnogo-obrazovaniya",
  "rules": [
    {
      "description": "Организация должна иметь действующую лицензию на образовательную деятельность.",
      "severity": "critical",
      "category": "license",
      "condition": {
        "field": "documents.education_license.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Объём программы должен составлять не менее 72 часов.",
      "severity": "critical",
      "category": "duration",
      "condition": {
        "field": "curriculum.total_hours",
        "op": "ge",
        "value": 72
      }
    },
    {
      "description": "Не менее 80% преподавателей должны иметь профильную квалификацию.",
      "severity": "critical",
      "category": "staff",
      "condition": {
        "field": "staff.qualified_teachers_pct",
        "op": "ge",
        "value": 80
      }
    },
    {
      "description": "Допустимый формат реализации — только очный или смешанный.",
      "severity": "critical",
      "category": "delivery-format",
      "condition": {
        "field": "programme.delivery_format",
        "op": "in",
        "value": [
          "очно",
          "смешанно"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "energy-efficiency-subsidy",
  "rules": [
    {
      "description": "The project must reduce energy consumption by at least 20%.",
      "severity": "critical",
      "category": "energy_reduction",
      "condition": {
        "field": "project.energy_consumption_reduction_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "The applicant's co-financing share must be at least 30%.",
      "severity": "critical",
      "category": "co_financing",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 30
      }
    },
    {
      "description": "The application must include the object's technical passport.",
      "severity": "critical",
      "category": "documentation",
      "condition": {
        "field": "documents.technical_passport.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The works must be completed no later than December 31, 2027.",
      "severity": "critical",
      "category": "deadline",
      "condition": {
        "field": "project.completion_date",
        "op": "le",
        "value": "2027-12-31"
      }
    }
  ]
}

{
  "ruleset_id": "fond-nordstar-main-track-v2-4",
  "rules": [
    {
      "description": "Applications for the main track are ineligible when the organization has been registered for fewer than 24 months.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "org_v2.months_registered",
        "op": "lt",
        "value": 24
      }
    },
    {
      "description": "The requested grant amount must not exceed 250000 euros.",
      "severity": "critical",
      "category": "budget",
      "condition": {
        "field": "org_v2.total_requested",
        "op": "gt",
        "value": 250000
      }
    },
    {
      "description": "Applications without an independent audit report for the last completed financial year are rejected.",
      "severity": "critical",
      "category": "audit",
      "condition": {
        "field": "documents.audit_report.present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Applications submitted after 31 March 2027 are not accepted for the 2027 cycle.",
      "severity": "critical",
      "category": "deadline",
      "condition": {
        "field": "org_v2.submission_date",
        "op": "after",
        "value": "2027-03-31"
      }
    },
    {
      "description": "The headcount declared in the application must match the headcount in the annual report.",
      "severity": "major",
      "category": "consistency",
      "condition": {
        "field": "org_v2.declared_headcount",
        "op": "consistent",
        "value": null,
        "fields": [
          "org_v2.declared_headcount",
          "annual_report.headcount"
        ]
      }
    },
    {
      "description": "The annual report must be prepared under IFRS; a non-IFRS report is a formal deficiency.",
      "severity": "minor",
      "category": "reporting_standard",
      "condition": {
        "field": "annual_report.ifrs",
        "op": "eq",
        "value": false
      }
    }
  ]
}

{
  "ruleset_id": "fond-primer-grants-2026",
  "rules": [
    {
      "description": "The applicant organization must have been registered for at least 12 months on the submission date.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "application_form.months_registered",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "The requested grant amount must not exceed 100000 euros.",
      "severity": "major",
      "category": "budget_limit",
      "condition": {
        "field": "application_form.requested_total_eur",
        "op": "le",
        "value": 100000
      }
    },
    {
      "description": "Equipment expenses must not exceed 40 percent of the total budget.",
      "severity": "major",
      "category": "budget_composition",
      "condition": {
        "field": "budget.row.equipment.share_pct",
        "op": "le",
        "value": 40
      }
    },
    {
      "description": "The application form must be present.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.application_form.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The detailed budget must be present.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.budget.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The registration certificate or registry extract must be present.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.registration_cert.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The latest financial statement must be present.",
      "severity": "critical",
      "category": "required_document",
      "condition": {
        "field": "documents.finance_statement.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The application submission date must be no later than 1 October 2026.",
      "severity": "major",
      "category": "deadline",
      "condition": {
        "field": "application_form.submission_date",
        "op": "le",
        "value": "2026-10-01"
      }
    },
    {
      "description": "The application form must be signed by the legal representative.",
      "severity": "critical",
      "category": "signature",
      "condition": {
        "field": "application_form.signature_present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The requested amount in the application form must exactly match the total of the detailed budget.",
      "severity": "major",
      "category": "consistency",
      "condition": {
        "op": "consistent",
        "fields": [
          "application_form.requested_total_eur",
          "budget.totals.total"
        ]
      }
    },
    {
      "description": "The financial statement must cover FY2025.",
      "severity": "major",
      "category": "reporting_period",
      "condition": {
        "field": "finance_statement.period",
        "op": "eq",
        "value": "FY2025"
      }
    }
  ]
}

{
  "ruleset_id": "capital-repair-program",
  "rules": [
    {
      "description": "Дом должен быть построен не позднее 2005 года.",
      "severity": "critical",
      "category": "construction",
      "condition": {
        "field": "building.construction_year",
        "op": "le",
        "value": 2005
      }
    },
    {
      "description": "Решение собственников должны поддержать не менее 66% голосов.",
      "severity": "critical",
      "category": "approval",
      "condition": {
        "field": "owners.approval_pct",
        "op": "ge",
        "value": 66
      }
    },
    {
      "description": "К заявке должен прилагаться акт обследования дефектов.",
      "severity": "critical",
      "category": "documentation",
      "condition": {
        "field": "documents.defect_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявка должна быть подана не позднее 1 апреля 2027 года включительно.",
      "severity": "critical",
      "category": "deadline",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2027-04-01"
      }
    }
  ]
}

{
  "ruleset_id": "preferential-microloan-for-smes",
  "rules": [
    {
      "description": "The company's annual revenue must not exceed 120,000,000 rubles.",
      "severity": "critical",
      "category": "revenue",
      "condition": {
        "field": "company.annual_revenue_rub",
        "op": "le",
        "value": 120000000
      }
    },
    {
      "description": "The company must have no overdue debt.",
      "severity": "critical",
      "category": "overdue_debt",
      "condition": {
        "field": "company.overdue_debt",
        "op": "eq",
        "value": 0
      }
    },
    {
      "description": "At least 51% of the company's shares must be owned by Russian owners.",
      "severity": "critical",
      "category": "russian_ownership",
      "condition": {
        "field": "company.russian_ownership_pct",
        "op": "ge",
        "value": 51
      }
    },
    {
      "description": "The requested loan amount must not exceed 10,000,000 rubles.",
      "severity": "critical",
      "category": "loan_amount",
      "condition": {
        "field": "loan.requested_rub",
        "op": "le",
        "value": 10000000
      }
    }
  ]
}

{
  "ruleset_id": "municipal-subsidy-2026",
  "rules": [
    {
      "description": "The recipient must have been registered for at least 12 months.",
      "severity": "critical",
      "category": "registration",
      "condition": {
        "field": "applicant.registration_months",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "The requested subsidy must not exceed 5,000,000 rubles.",
      "severity": "critical",
      "category": "subsidy_amount",
      "condition": {
        "field": "application.requested_rub",
        "op": "le",
        "value": 5000000
      }
    },
    {
      "description": "The application must include financial statements for the last year.",
      "severity": "major",
      "category": "required_document",
      "condition": {
        "field": "documents.financial_statement.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The application must be submitted no later than September 15, 2026, inclusive.",
      "severity": "critical",
      "category": "deadline",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2026-09-15"
      }
    },
    {
      "description": "Organizations with tax arrears are not eligible.",
      "severity": "critical",
      "category": "tax_compliance",
      "condition": {
        "field": "applicant.tax_arrears",
        "op": "eq",
        "value": false
      }
    }
  ]
}

{
  "ruleset_id": "zakupka-remontnykh-rabot",
  "rules": [
    {
      "description": "The supplier's annual turnover must be at least 10,000,000 rubles.",
      "severity": "critical",
      "category": "financial_eligibility",
      "condition": {
        "field": "supplier.annual_turnover_rub",
        "op": "ge",
        "value": 10000000
      }
    },
    {
      "description": "The participant must have a valid SRO certificate.",
      "severity": "critical",
      "category": "qualification",
      "condition": {
        "field": "documents.sro_certificate.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The participant is admitted only if the sanctions screening status is clear.",
      "severity": "critical",
      "category": "sanctions",
      "condition": {
        "field": "supplier.sanctions_status",
        "op": "eq",
        "value": "clear"
      }
    },
    {
      "description": "Applications must be submitted no later than November 20, 2026.",
      "severity": "critical",
      "category": "submission_deadline",
      "condition": {
        "field": "bid.submission_date",
        "op": "le",
        "value": "2026-11-20"
      }
    }
  ]
}

{
  "ruleset_id": "konkurs-prikladnykh-issledovaniy",
  "rules": [
    {
      "description": "Руководитель должен иметь степень «кандидат наук» или «доктор наук».",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "researcher.degree",
        "op": "in",
        "value": [
          "кандидат наук",
          "доктор наук"
        ]
      }
    },
    {
      "description": "Руководитель должен иметь не менее трёх публикаций в рецензируемых журналах.",
      "severity": "critical",
      "category": "publications",
      "condition": {
        "field": "researcher.peer_reviewed_publications",
        "op": "ge",
        "value": 3
      }
    },
    {
      "description": "Должно быть согласие на размещение обезличенных данных исследования.",
      "severity": "critical",
      "category": "consent",
      "condition": {
        "field": "documents.open_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявленный в форме бюджет должен совпадать с итогом сметы.",
      "severity": "major",
      "category": "budget",
      "condition": {
        "op": "consistent",
        "fields": [
          "application.declared_budget_rub",
          "budget.total_rub"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "social-contract",
  "rules": [
    {
      "description": "The household must be located in Moscow or Moscow Oblast.",
      "severity": "critical",
      "category": "residency",
      "condition": {
        "field": "household.region",
        "op": "in",
        "value": [
          "Москва",
          "Московская область"
        ]
      }
    },
    {
      "description": "Monthly income per household member must not exceed 25,000 rubles.",
      "severity": "critical",
      "category": "income",
      "condition": {
        "field": "household.monthly_income_per_person_rub",
        "op": "le",
        "value": 25000
      }
    },
    {
      "description": "Consent to the processing of personal data is required.",
      "severity": "critical",
      "category": "consent",
      "condition": {
        "field": "documents.personal_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The applicant must have employment status unemployed or job_seeker.",
      "severity": "critical",
      "category": "employment",
      "condition": {
        "field": "applicant.employment_status",
        "op": "in",
        "value": [
          "unemployed",
          "job_seeker"
        ]
      }
    }
  ]
}
